    rows = []
    for r in range(h):
        vals = grid[r]
        if max(vals.count(v) for v in set(vals)) >= w - 2:
            rows.append(r)

    cols = []
    for c in range(w):
        vals = [grid[r][c] for r in range(h)]
        if max(vals.count(v) for v in set(vals)) >= h - 2:
            cols.append(c)

    # Keep the repeating marker lattice, excluding the outer terminal line.
    def lattice(indices):
        if len(indices) < 2:
            return indices
        gaps = [b - a for a, b in zip(indices, indices[1:])]
        from collections import Counter
        step = Counter(gaps).most_common(1)[0][0]
        return [x for x in indices if (x - indices[0]) % step == 0]

    rows = lattice(rows)
    cols = lattice(cols)
    if len(rows) > 1:
        rows = rows[:-1]
    if len(cols) > 1:
        cols = cols[:-1]

    # Replace the uniform lattice color (the grid's separator) by the
    # ordinary background color, preserving the marked intersection colors.
    allvals = [v for row in grid for v in row]
    from collections import Counter
    background = Counter(allvals).most_common(1)[0][0]
    line_colors = []
    for r in rows:
        line_colors.append(Counter(grid[r]).most_common(1)[0][0])
    separator = Counter(line_colors).most_common(1)[0][0]

    return [[background if grid[r][c] == separator else grid[r][c]
